// Each lesson names a concept; progress keys remain stable when the route is reordered.
window.expandCurriculum=(tracks,ids)=>{
 const add=(track,title,objective,explanation,formula,example,question,answers,correct,feedback,concept)=>{const l=[title,objective,explanation,formula,example,question,answers,correct,feedback,'current'];l.concept=concept;l.progressId=ids[track]+'-'+tracks[track].lessons.length;tracks[track].lessons.push(l);return l;};
 const concepts=[['measure','newton','energy','pressure','kinematics','friction'],['drivetrain','fourstroke','crank','cooling','differential','braking'],['boyle','airchain','valve','cylinder','atmosphere','throttle'],['pascal','pump','continuity','hydropower','hydrostatic','bernoulli'],['closed','ohm','networks','threephase','rectifier','capacitor'],['coil','alternator','motor','gears','relay','efficiency']];
 tracks.forEach((tr,i)=>tr.lessons.forEach((l,j)=>{l.concept=concepts[i][j];l.progressId=ids[i]+'-'+j}));
 add(0,'Vectores: fuerzas con dirección','Sumar componentes, no solo tamaños.','Una fuerza tiene módulo, dirección y sentido. Dos fuerzas de 10 N pueden sumar 20 N, anularse o producir un resultado intermedio según el ángulo. Para calcular la resultante, separa cada vector en sus componentes x e y, suma cada eje y reconstruye el vector total.','Fx = F cos θ; Fy = F sin θ; |F| = √(Fx² + Fy²)','Una fuerza de 10 N a 60° tiene Fx = 5 N y Fy ≈ 8,66 N. No son dos fuerzas nuevas: son otra forma de expresar la misma.','Dos fuerzas iguales y opuestas tienen resultante…',['Cero','El doble','Una fuerza perpendicular'],0,'Las componentes se cancelan por pares.','vectors');
 add(0,'Oscilación, frecuencia y resonancia','Distinguir amplitud, periodo y frecuencia natural.','Un sistema masa-resorte almacena energía alternativamente en movimiento y deformación. Su frecuencia natural depende de masa y rigidez. Si una fuerza periódica actúa cerca de esa frecuencia, puede aumentar la amplitud. El amortiguamiento disipa energía y limita la respuesta.','f₀ = (1/2π)√(k/m); T = 1/f','Con k = 100 N/m y m = 1 kg, f₀ ≈ 1,59 Hz. Al cuadruplicar la masa, la frecuencia se reduce a la mitad.','Si multiplicas la masa por cuatro, f₀…',['Se duplica','Se reduce a la mitad','Se cuadruplica'],1,'La masa aparece dentro de una raíz cuadrada en el denominador.','spring');
 add(4,'Onda senoidal: tiempo, amplitud y fase','Leer una señal AC punto por punto.','La onda senoidal describe una magnitud que cambia suavemente y repite su forma. La amplitud es su valor máximo respecto de cero. El periodo es el tiempo de un ciclo; la frecuencia cuenta ciclos por segundo. La fase indica en qué parte del ciclo está la señal respecto de una referencia. Cambiar frecuencia no cambia automáticamente amplitud.','v(t) = Vp sen(2πft + φ); T = 1/f','A 50 Hz, T = 20 ms. Para Vp = 100 V y fase cero, a los 5 ms la tensión vale +100 V; a 10 ms vale cero y a 15 ms vale −100 V.','Si subes de 50 a 100 Hz, el periodo…',['Pasa de 20 a 10 ms','Pasa de 20 a 40 ms','Sigue en 20 ms'],0,'T = 1/f: más ciclos por segundo significa menos tiempo por ciclo.','sine');
 add(4,'Valor eficaz RMS: qué significa realmente','Relacionar una señal alterna con su efecto térmico.','El promedio de una sinusoide centrada en cero es cero, pero su calentamiento no lo es. RMS significa raíz de la media del cuadrado. Primero se eleva la señal al cuadrado, después se promedia y al final se toma la raíz. Sobre una resistencia, una tensión RMS produce la misma potencia media que una DC de igual valor.','Vrms = Vp/√2 (solo sinusoide); P = Vrms²/R','Una sinusoide de 170 V de pico tiene unos 120,2 V RMS. En 120 Ω produce aproximadamente 120,4 W medios, aunque la tensión cambie de signo.','Para una sinusoide, el valor RMS es…',['Igual al pico','El pico dividido por √2','Siempre cero'],1,'La media del cuadrado del seno es 1/2.','rms');
 add(4,'Estrella y triángulo: fase no es línea','Comparar las magnitudes de una carga trifásica equilibrada.','En estrella cada impedancia conecta entre una línea y el punto común. En triángulo cada impedancia conecta entre dos líneas. En estrella la tensión de línea es √3 veces la tensión de cada carga. En triángulo cada carga ve directamente la tensión de línea. La conexión debe corresponder a la tensión nominal de los devanados.','Estrella: VL = √3 Vf, IL = If. Triángulo: VL = Vf, IL = √3 If','Con 400 V entre líneas, una carga en estrella recibe 230,9 V por fase; la misma impedancia en triángulo recibe 400 V. Conectar distinto cambia sus corrientes.','Con VL = 400 V, una fase en estrella recibe…',['400 V','230,9 V','692,8 V'],1,'400/√3 ≈ 230,9 V.','star');
 add(4,'Potencia activa, reactiva y aparente','Ver qué cambia cuando corriente y tensión se desfasan.','Una resistencia ideal tiene corriente en fase con tensión. Una inductancia almacena energía magnética y un condensador energía eléctrica; pueden devolverla a la fuente. En régimen sinusoidal, la potencia activa es la media de v(t)i(t), mientras que la aparente usa los valores RMS. El factor de potencia indica la relación entre ambas.','P = VI cos φ; Q = VI sen φ; S = VI; S² = P² + Q²','Con 120 V RMS, 5 A RMS y cos φ = 0,8, S = 600 VA y P = 480 W. Con carga inductiva, Q = 360 var. No son 600 W útiles.','Con V e I constantes, al reducir cos φ, P…',['Aumenta','Disminuye','No cambia'],1,'P es proporcional al factor de potencia.','powerac');
 add(4,'Transistor y PWM: controlar una carga','Distinguir una señal de control de la energía entregada.','Un transistor usado como interruptor conmuta la alimentación de una carga. PWM cambia la fracción del periodo durante la que permanece activado: el ciclo de trabajo D. Para una carga resistiva ideal alimentada entre 0 y V, la tensión media es DV y la potencia media es DV²/R. El valor RMS es V√D, no DV.','D = ton/T; Vmedia = DV; Vrms = V√D','Con pulsos de 12 V y D = 25 %, Vmedia = 3 V pero Vrms = 6 V. Una resistencia de 12 Ω disipa 3 W medios.','Al 25 %, el RMS de pulsos 0–12 V es…',['3 V','6 V','12 V'],1,'12√0,25 = 6 V; el promedio y el RMS no coinciden.','pwm');
 add(4,'Medir un circuito y localizar una falla','Elegir qué magnitud observar antes de concluir.','Medir tensión compara dos puntos; medir corriente exige conocer el camino de la corriente. Un circuito abierto puede conservar tensión en la fuente y tener corriente cero. Una resistencia mayor reduce la corriente para una tensión fija. Un síntoma debe contrastarse con un modelo: ausencia de corriente no implica ausencia de tensión.','Diagnóstico: hipótesis → magnitud esperada → comparación','En un circuito ideal de 12 V y 12 Ω esperas 1 A. Si el interruptor está abierto, esperas 0 A aunque la fuente siga mostrando 12 V.','Con interruptor abierto, una fuente ideal puede indicar…',['12 V y 0 A','0 V obligatoriamente','12 A'],0,'Un camino interrumpido impide la corriente sostenida.','diagnostic');
 add(5,'Transformador: flujo común, tensiones distintas','Relacionar espiras, tensión y corriente.','Un transformador utiliza un flujo magnético variable común a dos devanados. En el modelo ideal, la relación de tensiones coincide con la relación de espiras. La corriente cambia en sentido inverso para conservar potencia. Una alimentación DC estable no produce la transformación continua descrita por este modelo.','V₂/V₁ = N₂/N₁; V₁I₁ = V₂I₂ (ideal)','Con 200 espiras primarias y 100 secundarias, 120 V AC se transforman idealmente en 60 V. Si la salida entrega 2 A, la entrada toma 1 A.','Reducir tensión a la mitad idealmente permite…',['Duplicar corriente para igual potencia','Duplicar potencia sin entrada','Transformar DC estable'],0,'Se conserva potencia; la corriente cambia inversamente a la tensión.','transformer');
 add(5,'Motor DC: torque y fuerza contraelectromotriz','Conectar la electricidad con la carga mecánica.','La corriente de armadura produce torque. Al girar, el motor también genera una tensión interna que se opone a la alimentación. En régimen estacionario, la diferencia entre alimentación y esa tensión impulsa la corriente a través de la resistencia. Al aumentar carga, puede bajar velocidad y aumentar corriente.','V = RI + keω; τ = ktI','Con V = 24 V, R = 2 Ω y fuerza contraelectromotriz de 20 V, I = 2 A. Si la velocidad baja y esa tensión cae a 16 V, I = 4 A.','Si baja la fuerza contraelectromotriz con V fija, I…',['Aumenta','Disminuye','Siempre es cero'],0,'I = (V − E)/R.','dcmotor');
 add(5,'Motor paso a paso y posicionamiento','Relacionar secuencia eléctrica con ángulo.','El controlador energiza fases en una secuencia que desplaza la posición de equilibrio magnético del rotor. En un modelo de 200 pasos por vuelta, cada paso completo es 1,8°. Contar pulsos permite estimar posición, pero una carga excesiva puede causar pérdida de pasos si no hay realimentación.','Ángulo = pasos × 360° / pasos por vuelta','Con 200 pasos/vuelta, 50 pasos representan 90°. El microstepping suaviza el movimiento, pero no garantiza por sí solo exactitud bajo cualquier carga.','50 pasos de 1,8° equivalen a…',['9°','90°','180°'],1,'50 × 1,8 = 90°.','stepper');
 add(5,'Variador de frecuencia y velocidad','Separar frecuencia eléctrica y velocidad mecánica.','Un variador sintetiza alimentación AC a partir de un enlace DC mediante conmutación electrónica. La frecuencia determina la velocidad del campo del motor. En control V/f básico, se ajusta también tensión para mantener aproximadamente el flujo por debajo de la velocidad base. La velocidad real de un motor de inducción depende del deslizamiento.','ns = 120f/p; n = ns(1 − s)','Un motor de 4 polos tiene ns = 1 500 rpm a 50 Hz y 900 rpm a 30 Hz. Con s = 4 %, a 30 Hz el rotor gira a 864 rpm.','Para 4 polos y 30 Hz, ns es…',['900 rpm','1 800 rpm','30 rpm'],0,'120 × 30 / 4 = 900.','vfd');
 add(2,'Tratamiento del aire y caída de presión','Seguir qué cambia entre depósito y actuador.','El aire transporta humedad y puede arrastrar partículas. El tratamiento se adapta a la aplicación. Un filtro presenta resistencia al flujo; la presión aguas abajo puede bajar más cuando aumenta el caudal o el elemento se obstruye. El regulador necesita margen de alimentación para mantener su ajuste.','Δp = p entrada − p salida','Si antes del filtro hay 7 bar y después 6,5 bar, su caída de presión es 0,5 bar en ese punto de funcionamiento. Un manómetro aislado no distingue obstrucción y falta de suministro.','La caída se calcula…',['Restando presiones','Sumando diámetros','Multiplicando tiempos'],0,'Se comparan presiones antes y después bajo condiciones conocidas.','filter');
 add(2,'Secuencia de un cilindro con sensores','Construir un ciclo de avance y retorno.','Un control secuencial usa estados. Desde reposo, una orden activa la válvula para avanzar. El sensor de fin de avance permite cambiar al retorno; el sensor de inicio confirma el regreso. Un tiempo agotado sin alcanzar el sensor debe producir un estado de fallo, no una orden ciega de continuar.','Reposo → avance → fin de avance → retorno → inicio','Si el sensor de avance no se activa, el control no tiene confirmación de posición. La animación permite interrumpir la detección y observar la secuencia.','¿Qué confirma el final del avance?',['El sensor de posición','Solo el tiempo programado','La presión ambiente'],0,'El tiempo puede limitar una maniobra, pero no prueba que se alcanzó la posición.','sequence');
 tracks.push({title:'Mecatrónica y automatización',intro:'Integra mecánica, sensores, electrónica y programación en una máquina que observa y actúa.',lessons:[]});ids.push('mechatronics');
 add(6,'Una máquina que percibe y actúa','Identificar sensor, controlador y actuador.','La mecatrónica integra un mecanismo físico con electrónica y control. Un sensor convierte una magnitud en información; el controlador toma decisiones; una etapa de potencia entrega energía al actuador. La realimentación cierra el ciclo al medir el resultado. La información y la energía recorren caminos distintos.','Medir → decidir → actuar → volver a medir','En una cinta clasificadora, una fotocélula detecta la pieza, el controlador espera su llegada y un actuador la desvía. El sensor no aporta la energía de empuje.','¿Qué entrega energía mecánica a la pieza?',['El actuador','El dato del sensor','La variable de software'],0,'El actuador convierte energía de alimentación en trabajo.','system');
 add(6,'Sensores analógicos y conversión digital','Relacionar una magnitud física con un número.','Un sensor analógico puede entregar una tensión proporcional a una magnitud. Un ADC la cuantiza en niveles discretos. Para un ADC ideal de 10 bits hay 1 024 códigos. La resolución es el tamaño del escalón; no equivale a exactitud. Ruido, calibración y referencia también importan.','Niveles = 2ⁿ; paso ideal ≈ Vref / 2ⁿ','Con 10 bits y referencia de 5 V, un paso es unos 4,88 mV. Un sensor 0–5 V para 0–100 °C ofrece un paso nominal de 0,0977 °C.','Más bits reducen…',['El tamaño del escalón ideal','Toda fuente de error','La temperatura real'],0,'Aumentan los niveles; no eliminan errores de calibración.','adc');
 add(6,'Encoder: contar movimiento','Interpretar pulsos y sentido de giro.','Un encoder incremental genera pulsos al moverse. Dos canales en cuadratura, A y B, permiten inferir sentido por cuál adelanta al otro. El número de cuentas por vuelta depende del sensor y del modo de decodificación. Tras perder alimentación, un incremental necesita una referencia para recuperar posición absoluta.','Ángulo = cuentas × 360° / cuentas por vuelta','Con 400 cuentas/vuelta después de decodificación, 100 cuentas son 90°. No confundas pulsos por canal con cuentas del decodificador.','¿Qué aporta la cuadratura A/B?',['Sentido de giro','Torque adicional','Alimentación del motor'],0,'El orden temporal de A y B revela el sentido.','encoder');
 add(6,'PWM y etapa de potencia','Controlar energía desde una señal lógica.','Un microcontrolador entrega una señal de mando; un driver y un transistor conmutan la energía de una fuente hacia la carga. PWM no es una tensión analógica continua: es una sucesión de pulsos. La respuesta del actuador depende de su dinámica y de la frecuencia de conmutación.','D = ton/T; media ideal de pulsos = DV','Un mando del 60 % aplicado a pulsos de 12 V tiene 7,2 V de media. En un motor no basta esa media para calcular corriente sin su modelo eléctrico y mecánico.','PWM del 60 % significa activado…',['60 % del periodo','60 segundos siempre','A 60 V'],0,'El porcentaje describe una fracción de cada ciclo.','driver');
 add(6,'Lazo abierto y lazo cerrado','Comprender para qué sirve medir el resultado.','En lazo abierto se manda una acción sin comparar su resultado con una referencia. En lazo cerrado, se mide la salida y se calcula el error. El controlador modifica la actuación para reducirlo. Las limitaciones del actuador y el retraso de medida pueden impedir seguir cambios rápidos.','Error e = referencia − medida','Si deseas 80 mm y el sensor mide 65 mm, e = 15 mm. Un controlador proporcional aumenta el mando con ese error, pero una perturbación puede dejar error estacionario.','Si referencia y medida coinciden, e vale…',['Cero','La referencia','La suma'],0,'e = r − y.','feedback');
 add(6,'Control proporcional y PI','Observar respuesta, error y saturación.','El término proporcional responde al error actual. El integral acumula error y puede eliminar el error estacionario frente a perturbaciones constantes. Un ajuste demasiado agresivo puede causar sobreimpulso u oscilaciones. Cuando el actuador satura, conviene evitar que el integrador siga acumulando sin efecto.','u = Kp e + Ki ∫e dt','Un controlador PI de posición compara referencia y sensor en cada paso. Prueba aumentar Kp y después Ki; observa cómo cambian la rapidez, el error final y el sobreimpulso en el modelo simplificado.','El término integral responde a…',['Error acumulado','Solo velocidad máxima','Número de cables'],0,'Integra el error a lo largo del tiempo.','pi');
 add(6,'PLC: entradas, lógica y salidas','Leer una secuencia de control discreto.','Un PLC procesa entradas, ejecuta lógica y actualiza salidas de acuerdo con su arquitectura de ciclo. Una máquina se describe con estados y condiciones de transición. Los enclavamientos evitan órdenes incompatibles. Un ejemplo educativo de lógica no sustituye funciones de seguridad certificadas.','Estado siguiente = función(estado, entradas)','En el ciclo de una pinza: detectar pieza, cerrar, confirmar cierre y mover. Si falta confirmación de cierre, no se autoriza el movimiento siguiente.','Una transición fiable requiere…',['La condición definida','Solo una animación bonita','Ignorar sensores'],0,'El estado avanza cuando se cumplen sus condiciones.','plc');
 add(6,'Proyecto: clasificador de piezas','Integrar detección, temporización y expulsión.','La cinta transporta piezas a velocidad conocida. Un sensor detecta la pieza y el control calcula cuándo llegará al actuador. El retardo nominal es distancia dividida por velocidad. Si la velocidad cambia, un retardo fijo produce error; un encoder permite sincronizar con desplazamiento real.','t llegada = distancia / velocidad','Con 0,30 m entre sensor y expulsor y cinta a 0,15 m/s, el retardo es 2 s. Al duplicar velocidad, debe bajar a 1 s.','Si duplicas velocidad, el retardo ideal…',['Se reduce a la mitad','Se duplica','No cambia'],0,'t = d/v.','sorter');
 const rc=tracks[4].lessons.find(l=>l.concept==='capacitor');rc[0]='Condensadores: carga y descarga RC';rc[1]='Relacionar corriente, tensión y constante de tiempo.';rc[2]='Un condensador almacena energía en un campo eléctrico. Su tensión depende de la carga acumulada. Al conectarlo a una fuente a través de una resistencia, la carga progresa exponencialmente: la corriente empieza alta y disminuye. Al descargarlo por una resistencia, la tensión decae exponencialmente. La constante de tiempo RC determina el ritmo de ambos procesos.';
 // Separate combined topics: the original progress keys continue to refer to the same lesson.
 tracks[4].lessons=[0,1,2,6,7,3,8,9,4,5,10,11].map(i=>tracks[4].lessons[i]);
 tracks[4].lessons[2][0]='Resistencias en serie y paralelo';
 tracks[4].lessons[2][1]='Seguir tensión y corriente en cada rama.';
 tracks[4].lessons[2][2]='En serie hay un único camino: la misma corriente atraviesa cada resistencia y la tensión total se reparte. En paralelo las ramas conectan los mismos dos nodos: comparten tensión y sus corrientes se suman. La resistencia equivalente permite reemplazar toda la red por un solo componente visto desde sus terminales. Las leyes de Kirchhoff expresan conservación de carga en nodos y de energía a lo largo de un lazo.';
 tracks[4].lessons[2][3]='Serie: Req = R₁ + R₂. Paralelo: 1/Req = 1/R₁ + 1/R₂';
 tracks[4].lessons[2][4]='Dos resistencias de 12 Ω con 12 V: en serie, Req = 24 Ω e I = 0,5 A; cada una cae 6 V. En paralelo, Req = 6 Ω e Itotal = 2 A; cada rama lleva 1 A.';
 tracks[5].lessons[2][2]='Tres devanados distribuidos espacialmente y alimentados con corrientes separadas 120° eléctricos crean un campo magnético giratorio. En un motor de inducción ese campo induce corrientes en el rotor. La interacción produce torque. El rotor necesita una diferencia de velocidad respecto del campo para inducir corriente: el deslizamiento. La animación distingue la flecha del campo de la marca del rotor; la vista de dos polos representa directamente el ángulo mecánico.';
 tracks[5].lessons[2][4]='A 50 Hz y 2 polos, ns = 3 000 rpm. Con deslizamiento del 4 %, el rotor gira a 2 880 rpm. La reproducción visual se ralentiza para poder observar la diferencia.';
 tracks[5].lessons[2][5]='En un motor de inducción, la velocidad síncrona corresponde a…';tracks[5].lessons[2][6]=['El campo giratorio','Siempre el rotor','La corriente en un cable'];
 add(0,'Resonancia: cuando el ritmo amplifica el movimiento','Relacionar frecuencia de excitación, amortiguamiento y amplitud.','Una fuerza periódica puede entregar energía al oscilador en cada ciclo. La respuesta depende de la relación entre frecuencia aplicada y frecuencia natural. Cerca de la resonancia, una pequeña fuerza puede producir grandes desplazamientos. El amortiguamiento disipa energía y limita la amplitud. La animación compara la fuerza y la respuesta estacionaria, incluyendo su desfase.','M = 1/√((1 − r²)² + (2ζr)²); r = f/f₀','Para r = 1 y ζ = 0,1, M = 5. Con una deformación estática de 10 mm, la amplitud estacionaria es 50 mm. Si ζ pasa a 0,2, la amplitud se reduce a 25 mm.','En r = 1, duplicar ζ hace que la amplitud…',['Se reduzca a la mitad','Se duplique','Sea infinita'],0,'En ese punto M = 1/(2ζ).','resonance');
 add(0,'Ondas estacionarias: nodos y modos','Reconocer los patrones permitidos en una cuerda fija.','Dos ondas iguales que viajan en sentidos opuestos pueden superponerse y formar una onda estacionaria. Los nodos permanecen inmóviles y los vientres alcanzan la máxima amplitud. En una cuerda ideal fija en ambos extremos, solo encajan longitudes de onda con un número entero de medias ondas.','λn = 2L/n; fn = nv/(2L)','Con L = 1 m y v = 20 m/s, el primer modo tiene f₁ = 10 Hz. El tercero tiene f₃ = 30 Hz y dos nodos interiores.','El tercer modo de una cuerda fija tiene…',['Dos nodos interiores','Tres nodos interiores','Ningún nodo'],0,'Hay n − 1 nodos interiores, además de los dos extremos.','standing');
 add(5,'Secuencia de fases: por qué se invierte el giro','Ver la relación entre orden de fases y sentido del campo.','La secuencia ABC o ACB determina el orden temporal de los máximos de las tres fases. Intercambiar dos fases invierte la dirección de giro del campo equivalente. En un motor real el rotor no cambia de velocidad instantáneamente: la inercia y el control del accionamiento determinan el transitorio. Aquí se compara el campo en ambos órdenes.','ABC ↔ ACB: inversión del campo; ns = 120f/p','En un motor equivalente de dos polos a 50 Hz, el campo gira a 3 000 rpm. Al invertir la secuencia, cambia el signo de la velocidad, no su módulo.','Al intercambiar dos fases, el campo…',['Invierte el sentido','Duplica la frecuencia','Se detiene necesariamente'],0,'El orden espacial y temporal de las fases cambia de orientación.','phasesequence');
 add(3,'Cavitación: cuando el líquido forma vapor','Comparar presión absoluta local con presión de vapor.','Un líquido puede formar cavidades de vapor si la presión local cae hasta su presión de vapor a esa temperatura. Al llegar a una zona de mayor presión, las cavidades pueden colapsar. Este fenómeno es distinto de tener aire atrapado. En bombas importa el margen de presión en aspiración; un análisis real requiere propiedades del líquido y datos del equipo.','Margen local = p absoluta − p vapor(T)','Para agua a 20 °C, usamos p vapor ≈ 2,34 kPa. Si la presión local es 1,5 kPa absolutos, el margen es −0,84 kPa: el modelo indica condiciones favorables a cavitación.','Para comparar con presión de vapor debes usar presión…',['Absoluta','Manométrica sin corregir','Solo en bar'],0,'Ambas presiones deben tener la misma referencia absoluta.','cavitation');
 add(2,'Lógica neumática: válvulas AND y OR','Construir una condición de salida a partir de dos señales.','Una función AND requiere ambas señales de presión para producir salida. Una función OR permite salida cuando existe cualquiera de las dos. En neumática se implementan mediante componentes adecuados, como válvulas de simultaneidad y selectoras. La lógica binaria es una abstracción de presiones que deben superar un umbral.','AND: Y = A·B; OR: Y = A + B (álgebra lógica)','Con A = 1 y B = 0, AND produce 0 y OR produce 1. En el laboratorio, cada entrada se considera activa a partir de 3 bar.','Si A = 1 y B = 0, una función AND entrega…',['0','1','2'],0,'AND solo entrega uno cuando ambas entradas son uno.','airlogic');
 add(6,'Brazo robot: de ángulos a posición','Calcular dónde llega una herramienta con dos articulaciones.','La cinemática directa calcula posición a partir de los ángulos de las articulaciones. En un brazo plano de dos eslabones, el segundo ángulo se mide respecto del primero. La herramienta depende de θ₁ y de la suma θ₁ + θ₂. Diferentes configuraciones pueden alcanzar un mismo punto. La cinemática no calcula por sí sola fuerzas ni colisiones.','x = L₁cos θ₁ + L₂cos(θ₁ + θ₂); y = L₁sen θ₁ + L₂sen(θ₁ + θ₂)','Con L₁ = 200 mm, L₂ = 150 mm, θ₁ = 0° y θ₂ = 90°, la herramienta está en (200, 150) mm. Con ambos ángulos en cero llega a (350, 0) mm.','Con ambos ángulos en cero, el alcance es…',['350 mm','50 mm','250 mm'],0,'Los dos eslabones están alineados y sus longitudes se suman.','robotarm');

 add(4,'Transformador bajo carga: seguir la potencia','Relacionar espiras, tensión, corriente y potencia.','Dos bobinas comparten un núcleo magnético, pero no una conexión conductora ideal. La corriente alterna del primario produce flujo variable y este induce tensión en el secundario. La relación de espiras transforma la tensión; con carga resistiva, la corriente del primario cambia para conservar la potencia ideal. Elevar tensión no multiplica energía. Una tensión continua sostenida no produce la transformación periódica mostrada.','Vs/Vp = Ns/Np; Vp Ip = Vs Is; Is = Vs/R','Con Vp = 24 V RMS, relación Ns/Np = 2 y carga de 48 Ω: Vs = 48 V, Is = 1 A, potencia = 48 W e Ip = 2 A. Al duplicar las espiras secundarias con la misma carga, la potencia solicitada se cuadruplica.','Si la relación es 0,5 con 24 V RMS en el primario, Vs es…',['12 V RMS','48 V RMS','24 V RMS'],0,'24 × 0,5 = 12 V RMS. El laboratorio muestra amplitudes instantáneas y lecturas RMS por separado.','transformload');
 add(4,'Amplificador operacional: ganancia y saturación','Distinguir amplificación lineal de recorte.','Un operacional usa energía de sus alimentaciones para producir una salida. En la configuración no inversora, una red de realimentación devuelve parte de la salida al terminal negativo. Con realimentación negativa y dentro del rango lineal, la ganancia ideal es 1 + Rf/Rg. La salida no puede crecer sin límite: al alcanzar los rieles se recorta. La onda pierde su forma aunque la entrada siga siendo sinusoidal.','G = 1 + Rf/Rg; salida ideal = G × entrada','Con Rg = 10 kΩ y Rf = 40 kΩ, G = 5. Una entrada de 1 V pico pide 5 V pico. Una de 3 V pico pide 15 V, pero el modelo alimentado a ±12 V la limita a ±12 V.','Con ganancia 5 y entrada de 3 V pico, la salida de este modelo…',['Se recorta a ±12 V','Llega a ±15 V','Siempre vale cero'],0,'La realimentación no elimina los límites de alimentación. Los operacionales reales pueden tener menos margen que este modelo ideal.','opamp');
 add(3,'Válvula de alivio: adónde va el caudal sobrante','Separar presión, caudal útil y calentamiento.','Una bomba de desplazamiento positivo aporta caudal. La carga ofrece resistencia al movimiento y establece la presión necesaria. Una válvula de alivio limita la presión desviando caudal al depósito cuando se alcanza su ajuste. Si la presión requerida por la carga supera ese ajuste, el cilindro no avanza y la potencia hidráulica se disipa en el retorno. Subir el ajuste no aumenta el caudal de la bomba.','p requerida = F/A; v = Q/A; P = pQ','Con A = 10 cm², caudal = 6 L/min y carga = 4 kN se necesitan 40 bar. Un ajuste de 60 bar permite v = 0,10 m/s. Con carga de 8 kN se requieren 80 bar: el alivio a 60 bar deriva los 6 L/min y disipa 600 W.','Si la carga exige 80 bar y el alivio limita a 60 bar, el cilindro…',['Se queda detenido','Avanza más rápido','Recibe 80 bar igualmente'],0,'La fuerza disponible es insuficiente. El caudal vuelve al tanque; no desaparece.','relief');

};
